<script setup lang="ts">
import { shallowRef, watch } from 'vue'
import { discoveryStatuses, severityLabels, type DiscoveryDetail } from '@sky/environment'
import EvidenceImage from './EvidenceImage.vue'
const props = defineProps<{ detail: DiscoveryDetail; disabled: boolean }>()
defineEmits<{ review: [input: { decision: 'confirm' | 'reject'; severity: string; reason: string }]; focus: [] }>()
const severity = shallowRef('medium'), reason = shallowRef('')
watch(() => props.detail.id, () => { severity.value = 'medium'; reason.value = '' })
</script>
<template><section class="card"><div class="heading"><h2>2 · 影像证据与人工复核</h2><el-button @click="$emit('focus')">定位发现点</el-button></div><h3>{{ detail.title }} · {{ discoveryStatuses[detail.status] }}</h3><p>发现 {{ detail.id }} · 关联巡检 {{ detail.taskId }} · 用户标注WGS84 {{ detail.longitude }}, {{ detail.latitude }}</p><p>用户声明来源：{{ detail.imageSource === 'simulation' ? '仿真/示例' : '用户实拍资料（来源未验证）' }} · 采集 {{ detail.observedAt }} UTC · 标注来源 {{ detail.analysisSource }}（当前框由人工提交）</p><p v-if="detail.visionAnalysis">关联分析 {{ detail.visionAnalysis.id }} · 模型 {{ detail.visionAnalysis.modelName }} · 原始检出 {{ detail.visionAnalysis.result.predictions.length }} 个；原始预测与人工提交框分别保留。</p><EvidenceImage :discovery-id="detail.id" :boxes="detail.annotations" /><p class="hash">发现图片 SHA-256：{{ detail.imageSha256 }} · {{ detail.imageWidth }} × {{ detail.imageHeight }}</p><p v-for="(b, i) in detail.annotations" :key="i">标注 {{ i + 1 }}：{{ b.note || '未填写说明' }}</p>
  <div v-if="detail.status === 'pending_review'" class="review"><label>人工确认等级<select v-model="severity" aria-label="复核事件等级" :disabled="disabled"><option value="low">低</option><option value="medium">中</option><option value="high">高</option></select></label><label>复核原因<input v-model="reason" aria-label="环境复核原因" maxlength="500" :disabled="disabled"></label><el-button type="primary" :disabled="disabled || !reason.trim()" @click="$emit('review', { decision: 'confirm', severity, reason })">确认异常并生成事件</el-button><el-button type="warning" :disabled="disabled || !reason.trim()" @click="$emit('review', { decision: 'reject', severity, reason })">驳回发现</el-button></div>
  <p v-else>复核：{{ detail.reviewedBy }} · {{ detail.reviewedAt }} · {{ severityLabels[detail.severity ?? ''] }}等级 · {{ detail.reviewReason }}</p>
  <template v-if="detail.status === 'closed'"><h3>处置后证据（人工提交）</h3><EvidenceImage :discovery-id="detail.id" after /><p class="hash">处置后 SHA-256：{{ detail.afterSha256 }}</p><p>{{ detail.resolvedBy }} · {{ detail.resolvedAt }}：{{ detail.resolution }}</p></template>
</section></template>
<style scoped>.card { padding:20px; border:1px solid #24465d; background:#0b2132; }.card h2 { margin:0; font-size:17px; }.card h3 { font-size:15px; }.card p { font-size:12px; color:#a1bed0; line-height:1.8; }.heading,.review { display:flex; flex-wrap:wrap; gap:14px; align-items:center; }.heading { justify-content:space-between; }.review { align-items:end; margin-top:16px; }.review label { display:grid; gap:7px; font-size:12px; color:#acc7d8; }.review input,.review select { padding:9px; border:1px solid #31546b; background:#102a3d; color:#e1f1fa; }.review input { width:300px; }.hash { overflow-wrap:anywhere; }</style>
